"pkglib.note.body": "গেম pkg-এর জন্য সবচেয়ে পরিচ্ছন্ন উপায়। ইনস্টলের সময় ps5upload payload সাময়িকভাবে DPI loader দিয়ে বদলে দেওয়া হয় এবং কাজ শেষে আবার ফিরিয়ে আনা হয়, তাই সংযোগ কয়েক সেকেন্ডের জন্য বিঘ্নিত হতে পারে। গেম pkg সবচেয়ে ভালো কাজ করে; কিছু সিস্টেম (NPXS) pkg-এর জন্য এখনও PS5-এর নিজস্ব Settings → Package Installer লাগতে পারে।",
