upload_streams_off: "1 (একক)",
upload_streams_hint: "ডিফল্ট 1 (একক স্ট্রিম) — সবচেয়ে স্থিতিশীল পথ, নন-প্রো কনসোলগুলিতে প্রায় 40 মেগাবাইট/সেকেন্ড (একটি থ্রেড সীমা, আপনার নেটওয়ার্ক বা এসএসডি নয়) । দ্রুততর হওয়ার জন্য এটি একবারে বেশ কয়েকটি সংযোগের উপর বড় ফোল্ডার আপলোড করে, তবে নীচের সতর্কতাটি দেখুন । শুধুমাত্র সংযুক্ত পেলোড এর সমর্থিত সর্বোচ্চ ব্যবহার করা হয় ।",
upload_streams_unsupported: "সংযুক্ত পেলোডটি এখনও একাধিক স্ট্রিম সমর্থন করে না — আপডেট না হওয়া পর্যন্ত আপলোডগুলি একটি স্ট্রিম ব্যবহার করবে ।",
upload_streams_unstable: "দ্রুত, তবে সতর্কতার সাথে ব্যবহার করুন: 1 টিরও বেশি স্ট্রিম একবারে PS5 এর বিরুদ্ধে বেশ কয়েকটি স্থানান্তর চালায় এবং কিছু কনসোলগুলিতে যা পে-লোডটি মিড-আপলোডে ক্র্যাশ করতে পারে (আপনি এটি পুনরায় লোড না করা পর্যন্ত এটি প্রতিক্রিয়া বন্ধ করে দেয়) । যদি আপলোডগুলি ব্যর্থ হতে শুরু করে বা পেলোড ড্রপ হয়, তবে এটি 1 এ সেট করুন — একক-স্ট্রিম পথটি সবচেয়ে স্থিতিশীল ।",
upload_auto_resume: "ব্যর্থতার পরে স্বয়ংক্রিয়ভাবে আপলোডগুলি পুনরায় চালু করুন",
upload_auto_resume_hint: "যদি কোনও আপলোডের মধ্যবর্তী ট্রান্সফার ড্রপ হয় — প্রায়শই PS5 পেলোড ক্র্যাশ হওয়ার কারণে — স্বয়ংক্রিয়ভাবে পে-লোডটি পুনরায় পাঠান এবং যেখান থেকে এটি ছেড়ে গিয়েছিল সেখান থেকে আবার শুরু করুন, হাল ছেড়ে দেওয়ার আগে কয়েকবার পুনরায় চেষ্টা করুন । PS5 এর মতো মারাত্মক সমস্যাগুলি এখনও স্থানের বাইরে চলে যাচ্ছে । ডিফল্টরূপে চালু ।",
