reset_hint: "PS5Upload এর প্রতিটি স্থানীয় ট্রেস মুছুন এবং শুরু করুন: সেটিংস, সংরক্ষিত PS5s, কার্যকলাপ/সারির ইতিহাস, পেলোড ক্যাশে এবং ক্র্যাশ রিপোর্ট । আপনার PS5-এ কোনও কিছু প্রভাবিত হয় না । আপনি যদি এটি ফেরত চান তবে প্রথমে একটি ব্যাকআপ রফতানি করুন ।",
