keep_ps5_awake_mode_hint: "পর্যায়ক্রমে PS5-এর অটো-স্ট্যান্ডবাই টাইমার রিসেট করুন যাতে এটি রেস্ট মোডে না পড়ে । \"স্থানান্তরের সময়\" দীর্ঘ আপলোডগুলি রক্ষা করে (ব্যর্থ আপলোডগুলির একটি সাধারণ কারণ; ডিফল্ট) । \"সর্বদা সংযুক্ত থাকা অবস্থায়\" যতক্ষণ না অ্যাপটি খোলা থাকে ততক্ষণ একজন চলমান হেল্পারের সাথে প্রতিটি কনসোলকে বিশ্রাম মোডে রাখে । PS5 কে ম্যানুয়ালি বিশ্রাম দেওয়া এখনও প্রতিটি মোডে কাজ করে ।",
