"pkglib.baseMissing.body": "এই {kind} {id}-এর জন্য, কিন্তু মূল গেমটি PS5-এ ইনস্টল করা নেই। Sony-র ইনস্টলার এটি গ্রহণ করবে, কিন্তু মূল গেম কনসোলে না আসা পর্যন্ত কিছুই ইনস্টল হবে না — আগে মূল গেমটি ইনস্টল করুন।",
"pkglib.baseMissing.bodyInLib": "এই {kind} {id}-এর জন্য, যার মূল গেমটি PS5-এ ইনস্টল করা নেই — তবে সেটি আপনার লাইব্রেরিতে আছে। আগে মূল গেমটি ইনস্টল করুন, তারপর এই {kind}। এখন {kind} ইনস্টল করলে তা গৃহীত হবে কিন্তু কার্যকর হবে না।",
"pkglib.baseMissing.installAnyway": "তবুও ইনস্টল করুন",
"pkglib.baseMissing.title": "মূল গেম ইনস্টল করা নেই",
"pkglib.external.autoScan": "এই ট্যাব খোলার সময় স্বয়ংক্রিয়ভাবে USB / বহিঃস্থ ড্রাইভ স্ক্যান করুন",
"pkglib.external.count": "{n}টি পাওয়া গেছে",
"pkglib.external.empty": "সংযুক্ত USB বা বহিঃস্থ ড্রাইভে কোনো .pkg ফাইল পাওয়া যায়নি। .pkg ফাইলসহ একটি ড্রাইভ সংযুক্ত করে স্ক্যান-এ ক্লিক করুন।",
"pkglib.external.failed": "ইনস্টল ব্যর্থ হয়েছে",
"pkglib.external.hint": "PS5-এ .pkg ফাইলসহ একটি USB বা বহিঃস্থ ড্রাইভ লাগান এবং সেগুলো এখানে দেখা যাবে — কোনো আপলোড প্রয়োজন নেই। ইনস্টল করার সময় ফাইলটি প্রথমে কনসোলে কপি হয় (আপনার ড্রাইভের কপি অক্ষত থাকে), তারপর ইনস্টল হয়। ড্রাইভ সংযুক্ত করার পর স্ক্যান ব্যবহার করুন।",
"pkglib.external.install": "ইনস্টল করুন",
"pkglib.external.installed": "ইনস্টল হয়েছে",
