"pkglib.external.notScanned": "স্বয়ংক্রিয় স্ক্যান বন্ধ। .pkg ফাইলসহ একটি USB বা বহিঃস্থ ড্রাইভ সংযুক্ত করে স্ক্যান-এ ক্লিক করুন।",
