"pkglib.installAll": "সব ইনস্টল করুন",
"pkglib.installAll.hint": "প্রস্তুত সব প্যাকেজ ইনস্টল করুন, আপডেট ও DLC-র আগে মূল গেমগুলো।",
"pkglib.installnote.body": "ps5upload আপনার হয়ে PS5-এ প্যাকেজ ইনস্টল করে। ইনস্টল চালাতে এটি সাময়িকভাবে পেলোড দখল করে (প্রয়োজনে DPI লোডারে ফিরে যায়) এবং শেষে তা ফিরিয়ে দেয়, তাই সংযোগ কয়েক সেকেন্ড থমকে যেতে পারে। FW 12+-এ স্ক্রিন কিছুক্ষণের জন্য কালো হয়ে যেতে পারে — এটি স্বাভাবিক। গেমের pkg সবচেয়ে ভালো কাজ করে; কিছু সিস্টেম pkg (NPXS)-এর জন্য এখনও PS5-এর নিজস্ব প্যাকেজ ইনস্টলার লাগতে পারে।",
"pkglib.installnote.title": "ইনস্টল কীভাবে কাজ করে",
"pkglib.menu.copyDetails": "বিস্তারিত কপি করুন",
"pkglib.menu.openFolder": "ফোল্ডার খুলুন",
"pkglib.options.heading": "বিকল্প",
"pkglib.stream": "Stream (বিটা)",
"pkglib.stream.fwLow.hint": "স্ট্রিম ইনস্টলের জন্য ফার্মওয়্যার ১১+ প্রয়োজন — আপনার আছে {fw}.x। পুরোনো ফার্মওয়্যারে HTTP পথটি আটকে যায়। বদলে আপলোড → ইনস্টল (স্টেজড) ব্যবহার করুন।",
"pkglib.stream.fwLow.message": "স্ট্রিম ইনস্টলের জন্য ফার্মওয়্যার ১১+ প্রয়োজন — আপনার আছে {fw}.x। পুরোনো ফার্মওয়্যারে HTTP ইনস্টল পথ আটকে যায়, কারণ Sony-র PlayGo প্রাক-যাচাই আমাদের কাছে না থাকা কার্নেল প্যাচ ছাড়া কখনো ফেরত আসে না। সাধারণ আপলোড → ইনস্টল (স্টেজড) ব্যবহার করুন — ফার্মওয়্যার {fw}-এ এটি ভালোভাবে কাজ করে।",
"pkglib.stream.hint": "কোনো স্টেজিং আপলোড ছাড়াই এই পিসি থেকে সরাসরি HTTP-র মাধ্যমে .pkg ইনস্টল করুন (বেটা)।",
"pkglib.version.title": "প্যাকেজ সংস্করণ (PARAM.SFO APP_VER)",
playlist_add_repo_step_hint: "এমন একটি ধাপ যোগ করুন যা রান-টাইমে একটি রিপোজিটরি থেকে আনা হয় — কোনো স্থানীয় ফাইল লাগে না।",
playlist_repo_picker_hint: "একটি পেলোড বেছে নিন। প্লেলিস্ট রান-টাইমে সর্বশেষ রিলিজ এনে ক্যাশ করে — তাই আপনাকে পিসিতে ফাইল রাখতে হয় না। ক্যাটালগ ট্যাবে নিজের রিপোজিটরি যোগ করুন।",
