processes_empty_user: "কোনো গেম বা পেলোড চলছে না। সবকিছু দেখতে “সিস্টেম প্রসেস দেখান” চালু করুন।",
processes_kill_app_body: "এটি চলমান গেম “{name}” জোর করে বন্ধ করবে। সংরক্ষণ না করা অগ্রগতি হারিয়ে যাবে। আবার চালু করতে চাইলে বদলে রিস্টার্ট ব্যবহার করুন।",
