fakelib_explain: "নতুন ফার্মওয়্যারের জন্য তৈরি গেমের সেই ফার্মওয়্যারের সিস্টেম লাইব্রেরি প্রয়োজন। সেগুলি এখানে রাখুন; BackPork গেম চালু হওয়ার সময় সেগুলি গেমে মাউন্ট করবে, মূল ফাইলগুলিতে হাত না দিয়ে। এটি কার্যকর করতে Payloads পর্দা থেকে BackPork পেলোড চালান।",
fakelib_explain_pair: "এটি ব্যাকপোর্টের দ্বিতীয় অর্ধাংশ — গেমের নিজের ফাইলগুলির প্রয়োজনীয় ফার্মওয়্যারও SDK সংস্করণ পরিবর্তনের পর্দায় নামাতে হবে। লাইব্রেরিগুলির সাধারণত আগে একটি BPS প্যাচ প্রয়োজন হয়, যাতে আপনার ফার্মওয়্যারে না থাকা ফাংশনগুলি সরানো যায়।",
