"pkglib.installAll.what": "“সব ইনস্টল করুন” কী?",
"pkglib.installAll.whatBody": "“সব ইনস্টল করুন” প্রস্তুত প্রতিটি প্যাকেজ ক্রমানুসারে চালায়: বেস গেম → আপডেট → DLC। একই সংস্করণের দুটি আপডেট (বা পরস্পরবিরোধী দুটি DLC) থাকলে প্রতিটি সারির চেকবক্স দিয়ে বেছে নিন এই কনসোল কোনটি ইনস্টল করবে — প্রতি গোষ্ঠীতে কেবল একটি। ওই গোষ্ঠীটি বাদ দিতে চেক তুলে দিন। একক সারির ইনস্টল বোতাম সর্বদা কেবল সেই প্যাকেজটিই ইনস্টল করে।",
"pkglib.variants.title": "একই সংস্করণের একটি প্যাকেজ রূপ বেছে নিন",
"pkglib.variants.body": "প্রস্তুত করা {n}টি প্যাচ/DLC রূপ একই টাইটেল ও সংস্করণকে লক্ষ্য করে। সবগুলিই রাখা হয়, কিন্তু PS5 ওই সংস্করণের জন্য কেবল একটি প্যাচই সক্রিয় রাখতে পারে। “সব ইনস্টল করুন” এগুলি এড়িয়ে যায়; এই কনসোলের সঙ্গে মানানসই Optional Fix বা Backport তার নিজের সারি থেকে ইনস্টল করুন।",
